<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useWorkspace} from '../store'
import {api,allPages,fmt} from '../api'
import Icon from '../components/Icon.vue'
import Status from '../components/Status.vue'
import Attachments from '../components/Attachments.vue'
import CaseMap from '../components/CaseMap.vue'
const mapMode=ref(false),copied=ref<any>(null),moduleList=ref<any[]>([]),importInput=ref<HTMLInputElement>()
const moduleFilter=ref<number|null>(null),generationDialog=ref(false),requirementList=ref<any[]>([]),generationSource=ref<number|null>(null),generationModule=ref('全部模块'),generationMode=ref('simulation'),generationModel=ref<number|null>(null),modelList=ref<any[]>([]),skillList=ref<any[]>([]),generationSkill=ref<number|null>(null),generationBusy=ref(false),generationJob=ref<any>(null)
const availableModules=computed(()=>moduleList.value.filter(m=>m.config?.source_requirement_id===generationSource.value))
async function loadModules(){if(store.projectId&&kind.value==='case')moduleList.value=await allPages('entities/',{project:store.projectId,kind:'module'})}
async function chooseRequirement(){if(!generationSource.value)return;await api.post(`entities/${generationSource.value}/sync_modules/`);await loadModules();generationModule.value='全部模块'}
async function openGenerate(){requirementList.value=await allPages('entities/',{project:store.projectId,kind:'requirement'});modelList.value=await allPages('resources/',{project:store.projectId,kind:'model'});skillList.value=(await allPages('resources/',{project:store.projectId,kind:'skill'})).filter(x=>x.enabled);generationSkill.value=skillList.value.find(x=>x.name==='ui-testcase-generation')?.id||null;generationSource.value=[...requirementList.value].sort((a,b)=>b.content.length-a.content.length)[0]?.id||null;generationMode.value=modelList.value.some(x=>x.mode==='live')?'live':'simulation';generationModel.value=modelList.value.find(x=>x.mode==='live')?.id||null;generationDialog.value=true;if(generationSource.value)await chooseRequirement()}
async function submitGenerate(){if(!generationSource.value){ElMessage.warning('请选择需求文档');return}if(generationMode.value==='live'&&!generationModel.value){ElMessage.warning('请选择模型');return}generationBusy.value=true;try{const selected=availableModules.value.find(x=>String(x.id)===generationModule.value);const focus=selected?.name||'全部模块';const {data}=await api.post('jobs/',{project:store.projectId,kind:'design',name:`生成用例 · ${focus}`,mode:generationMode.value,payload:{entity_id:generationSource.value,focus_module:focus,target_kind:'case',model_id:generationModel.value,...(generationSkill.value?{skill_ids:[generationSkill.value]}:{}),auto_apply:generationMode.value==='live'}});generationJob.value=data;generationDialog.value=false;ElMessage.success('生成任务已提交，后台正在处理')}finally{generationBusy.value=false}}
const generationTimer=setInterval(async()=>{if(!generationJob.value||generationJob.value._notified||generationJob.value.status==='failed')return;try{const {data}=await api.get(`jobs/${generationJob.value.id}/`);generationJob.value=data;if(data.status==='completed'&&data.applied){moduleFilter.value=null;page.value=1;await loadModules();await load();generationJob.value={...data,_notified:true};ElMessage.success('生成用例已写入测试用例列表')}else if(data.status==='completed'&&data.mode==='simulation'){generationJob.value={...data,_notified:true};ElMessage.info('模拟拆解已完成，未写入用例')}else if(data.status==='completed'&&data.result?.apply_error){generationJob.value={...data,_notified:true};ElMessage.error('用例写入失败：'+data.result.apply_error)}else if(data.status==='failed'){generationJob.value={...data,_notified:true};ElMessage.error(data.result?.error||'用例生成失败')}}catch{}},2500);onUnmounted(()=>clearInterval(generationTimer))
async function paste(){if(!copied.value)return;await api.post(`assets/${copied.value.id}/duplicate/`);ElMessage.success('已粘贴为新草稿');load()}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const data=new FormData();data.append('project',String(store.projectId));data.append('file',file);try{await api.post('assets/import/',data);ElMessage.success('导入完成');load()}finally{input.value=''}}
const store=useWorkspace(),route=useRoute(),router=useRouter(),kind=computed(()=>String(route.params.kind))
watch(()=>[route.query.generate,route.query.skill,store.projectId,kind.value],async()=>{if(route.query.generate!=='1'||!store.projectId||kind.value!=='case')return;await openGenerate();const requested=Number(route.query.skill);if(skillList.value.some(x=>x.id===requested))generationSkill.value=requested;router.replace({path:route.path,query:{}})},{immediate:true})
const names:Record<string,string>={document:'测试文档',case:'测试用例',plan:'测试计划',flow:'测试流程',suite:'测试套件'}
const descriptions:Record<string,string>={suite:'将可复用用例组织为测试套件，统一执行与追踪历史。',document:'集中管理需求、测试规范与参考文档，为测试建立共同上下文。',case:'沉淀测试步骤与预期结果，让每一次验证都有据可依。',plan:'组织测试范围与执行顺序，将测试用例汇聚为一次完整验证。',flow:'按顺序编排测试用例，构建可复用的自动化验证流程。'}
const items=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),status=ref(''),loading=ref(false),saving=ref(false),dialog=ref(false),detail=ref<any>(null),cases=ref<any[]>([]),agents=ref<any[]>([]),form=ref<any>({}),title=computed(()=>names[kind.value]||'测试资产')
let version=0
async function load(){if(!store.projectId)return;const v=++version;loading.value=true;try{const {data}=await api.get('assets/',{params:{project:store.projectId,kind:kind.value,page:page.value,search:search.value,status:status.value,...(kind.value==='case'&&moduleFilter.value?{module:moduleFilter.value}:{})}});if(v===version){items.value=data.results;total.value=data.count}}finally{if(v===version)loading.value=false}}
function filter(){page.value=1;load()}
watch(()=>[store.projectId,kind.value],()=>{page.value=1;dialog.value=false;detail.value=null;moduleFilter.value=null;load();loadModules()},{immediate:true})
async function edit(item?:any){moduleList.value=await allPages('entities/',{project:store.projectId,kind:'module'});agents.value=await allPages('resources/',{project:store.projectId,kind:'agent'});form.value=item?JSON.parse(JSON.stringify(item)):{name:'',description:'',priority:'P1',status:'draft',data:{steps:[{action:'',expected:''}],case_ids:[],simulate_result:'passed',content:''}};if(['plan','flow','suite'].includes(kind.value))cases.value=await allPages('assets/',{project:store.projectId,kind:'case'});dialog.value=true}
async function save(){if(!form.value.name?.trim()){ElMessage.warning('请填写名称');return}saving.value=true;try{const payload={name:form.value.name,description:form.value.description,priority:form.value.priority,status:form.value.status,data:form.value.data,project:store.projectId,kind:kind.value};if(form.value.id)await api.patch(`assets/${form.value.id}/`,payload);else await api.post('assets/',payload);dialog.value=false;ElMessage.success('已保存到数据库');await load();await store.loadProjects()}finally{saving.value=false}}
async function remove(item:any){try{await ElMessageBox.confirm(`确认删除「${item.name}」？其附件也会移除。`,'删除资产',{type:'warning'})}catch{return}await api.delete(`assets/${item.id}/`);if(items.value.length===1&&page.value>1)page.value--;await load();store.loadProjects()}
const executing=ref<number|null>(null)
async function execute(item:any){if(item.status!=='ready'){ElMessage.warning('该流程尚未就绪，请先编辑流程并将状态设为“就绪”');return}if(item.kind!=='case'&&!item.data?.case_ids?.length){ElMessage.warning('流程尚未关联测试用例，请先编辑流程并选择用例');return}executing.value=item.id;try{const {data}=await api.post('runs/',{source:item.id});ElMessage.success('模拟任务已进入后台队列');await router.push('/runs/'+data.id)}finally{executing.value=null}}
function exportUrl(){const p=new URLSearchParams({project:String(store.projectId),kind:kind.value,search:search.value,status:status.value});return '/api/assets/export/?'+p}
function move(index:number,delta:number){const ids=form.value.data.case_ids;[ids[index],ids[index+delta]]=[ids[index+delta],ids[index]]}
</script>
<template><div><div class="page-heading"><div><div class="heading-eyebrow">TEST ASSETS</div><h1>{{title}}<span class="heading-tag">{{total}}</span></h1><p>{{descriptions[kind]}}</p></div><div class="inline-actions"><a :href="exportUrl()" class="button-link"><Icon name="Download" :size="16"/>{{ $t('导出 CSV') }}</a><el-button v-if="store.canEdit" type="primary" @click="edit()"><Icon name="Plus"/>新建{{title}}</el-button></div></div>
 <div v-if="kind==='case'&&generationJob" class="info-banner"><Icon name="MagicStick"/><div><strong>生成任务 #{{generationJob.id}} · {{generationJob.status}}</strong><p>{{generationJob.mode==='live'?'真实模型生成':'模拟模式仅拆解原文，不生成用例'}} · 进度 {{generationJob.progress}}%</p></div><el-button link @click="router.push('/tasks/'+generationJob.id)">查看详情</el-button></div><div v-if="kind==='flow'" class="info-banner"><Icon name="SetUp"/><div><strong>{{ $t('让测试按你的方式推进') }}</strong><p>{{ $t('按用例顺序编排流程，后台依次执行；当前执行器为模拟模式，不调用外部服务。') }}</p></div></div>
 <div v-if="kind==='case'" class="case-actions"><el-radio-group v-model="mapMode"><el-radio-button :value="false">{{ $t('列表视图') }}</el-radio-button><el-radio-button :value="true">{{ $t('思维导图') }}</el-radio-button></el-radio-group><div class="inline-actions"><el-button v-if="store.canEdit" type="primary" @click="openGenerate">生成用例</el-button><el-button :disabled="!copied||!store.canEdit" @click="paste">{{ $t('粘贴副本') }}</el-button><el-button v-if="store.canEdit" @click="importInput?.click()">{{ $t('导入 CSV / JSON') }}</el-button><input ref="importInput" type="file" accept=".csv,.json" style="display:none" @change="importFile"/></div></div><CaseMap v-if="mapMode&&kind==='case'" @edit="edit" @changed="load"/><section v-else class="panel"><div class="list-toolbar"><div class="list-tabs"><b>全部{{title}}</b><span>{{total}}</span></div><div class="inline-actions"><el-input v-model="search" :placeholder="$t('搜索名称')" clearable style="width:230px" @keyup.enter="filter" @clear="filter"><template #prefix><Icon name="Search" :size="16"/></template></el-input><el-select v-if="kind==='case'" v-model="moduleFilter" clearable :value-on-clear="null" placeholder="全部模块" style="width:165px" @change="filter"><el-option v-for="m in moduleList" :key="m.id" :label="m.name" :value="m.id"/></el-select><el-select v-model="status" :placeholder="$t('全部状态')" clearable style="width:125px" @change="filter"><el-option :label="$t('草稿')" value="draft"/><el-option :label="$t('就绪')" value="ready"/><el-option :label="$t('已归档')" value="archived"/></el-select><el-button @click="filter">{{ $t('查询') }}</el-button></div></div>
 <el-table v-loading="loading" :data="items"><el-table-column :label="$t('名称')" min-width="260"><template #default="{row}"><div class="table-title"><span class="table-icon"><Icon :name="kind==='document'?'Document':'Tickets'" :size="18"/></span><div><el-button link class="asset-name" @click="detail=row">{{row.name}}</el-button><small>{{store.project?.key}}-{{String(row.id).padStart(3,'0')}}</small></div></div></template></el-table-column><el-table-column v-if="kind==='case'" label="所属模块" width="145"><template #default="{row}">{{moduleList.find(m=>m.id===row.data.module_id)?.name||row.data.feature||'未分配'}}</template></el-table-column><el-table-column :label="$t('优先级')" width="100"><template #default="{row}"><span class="priority" :class="row.priority">{{row.priority}}</span></template></el-table-column><el-table-column :label="$t('状态')" width="110"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column v-if="kind!=='document'" :label="kind==='case'?'测试步骤':'关联用例'" width="110"><template #default="{row}">{{kind==='case'?row.data.steps?.length||0:row.data.case_ids?.length||0}} {{kind==='case'?'步':'条'}}</template></el-table-column><el-table-column :label="$t('更新时间')" width="145"><template #default="{row}">{{fmt(row.updated_at)}}</template></el-table-column><el-table-column :label="$t('操作')" :width="kind==='document'?160:285"><template #default="{row}"><el-button v-if="store.canEdit&&kind!=='document'" link type="primary" :loading="executing===row.id" @click="execute(row)">{{ $t('模拟执行') }}</el-button><el-button v-if="store.canEdit" link type="primary" @click="edit(row)">{{ $t('编辑') }}</el-button><el-button v-else link @click="detail=row">{{ $t('查看') }}</el-button><el-button v-if="store.canEdit&&kind==='case'" link @click="copied=row;ElMessage.success('已复制，点击粘贴副本创建')">{{ $t('复制') }}</el-button><el-button v-if="store.canEdit" link type="danger" @click="remove(row)">{{ $t('删除') }}</el-button></template></el-table-column><template #empty><el-empty :description="`暂无${title}，点击右上角创建`"/></template></el-table><div class="pagination"><span>共 {{total}} 条记录</span><el-pagination v-model:current-page="page" :total="total" :page-size="10" layout="prev, pager, next" @current-change="load"/></div></section>
 <el-dialog v-model="generationDialog" title="按需求模块生成用例" width="600px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="需求文档"><el-select v-model="generationSource" filterable @change="chooseRequirement"><el-option v-for="r in requirementList" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="生成范围"><el-select v-model="generationModule"><el-option label="全部模块" value="全部模块"/><el-option v-for="m in availableModules" :key="m.id" :label="m.name" :value="String(m.id)"/></el-select></el-form-item><el-form-item label="生成 Skill"><el-select v-model="generationSkill" clearable :value-on-clear="null" placeholder="自动匹配 Skill"><el-option v-for="s in skillList" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="执行模式"><el-radio-group v-model="generationMode"><el-radio-button value="simulation">模拟拆解</el-radio-button><el-radio-button value="live">真实模型生成</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="generationMode==='live'" label="语言模型"><el-select v-model="generationModel" placeholder="选择已配置模型"><el-option v-for="m in modelList" :key="m.id" :label="m.name+(m.mode!=='live'?'（未验证）':'')" :value="m.id"/></el-select></el-form-item><p class="helper">系统根据需求规则和可测试场景自动确定用例数量。真实模型任务完成后，按模块写入测试用例列表，并保留源需求与规则编号。模拟拆解只展示结构，不生成用例。</p></el-form><template #footer><el-button @click="generationDialog=false">取消</el-button><el-button type="primary" :loading="generationBusy" @click="submitGenerate">开始生成</el-button></template></el-dialog>
 <el-dialog v-model="dialog" :title="`${form.id?'编辑':'新建'}${title}`" width="720px" :close-on-click-modal="false"><el-form label-position="top" @submit.prevent="save"><el-form-item :label="$t('名称 *')"><el-input v-model="form.name" maxlength="150" :placeholder="$t('例如：用户登录核心链路验证')"/></el-form-item><div class="form-grid"><el-form-item :label="$t('状态')"><el-select v-model="form.status"><el-option :label="$t('草稿')" value="draft"/><el-option :label="$t('就绪')" value="ready"/><el-option :label="$t('已归档')" value="archived"/></el-select></el-form-item><el-form-item :label="$t('优先级')"><el-select v-model="form.priority"><el-option v-for="p in ['P0','P1','P2','P3']" :key="p" :label="p" :value="p"/></el-select></el-form-item></div><el-form-item :label="$t('描述 / 前置条件')"><el-input v-model="form.description" type="textarea" :rows="2" maxlength="5000"/></el-form-item>
 <el-form-item v-if="kind!=='document'" :label="$t('执行 Agent（可选，仍为模拟执行）')"><el-select v-model="form.data.agent_id" clearable :value-on-clear="null" :placeholder="$t('内置模拟执行器')"><el-option v-for="a in agents" :key="a.id" :value="a.id" :label="a.name" :disabled="!a.enabled"/></el-select></el-form-item><template v-if="kind==='case'"><div class="form-grid"><el-form-item :label="$t('所属模块')"><el-select v-model="form.data.module_id" clearable :value-on-clear="null"><el-option v-for="m in moduleList" :key="m.id" :label="m.name" :value="m.id"/></el-select></el-form-item><el-form-item :label="$t('用例类型')"><el-select v-model="form.data.type"><el-option :label="$t('功能测试')" value="functional"/><el-option :label="$t('边界测试')" value="boundary"/><el-option :label="$t('异常测试')" value="negative"/><el-option :label="$t('安全测试')" value="security"/></el-select></el-form-item></div><el-form-item :label="$t('前置条件')"><el-input v-model="form.data.preconditions" type="textarea" :rows="2"/></el-form-item><el-form-item :label="$t('备注')"><el-input v-model="form.data.notes" type="textarea" :rows="2"/></el-form-item><div class="section-label">{{ $t('测试步骤') }}<el-button link type="primary" @click="form.data.steps.push({action:'',expected:''})">{{ $t('+ 添加步骤') }}</el-button></div><div v-for="(step,i) in form.data.steps" :key="i" class="step-editor"><span class="step-number">{{Number(i)+1}}</span><el-input v-model="step.action" :placeholder="$t('操作步骤')"/><el-input v-model="step.expected" :placeholder="$t('预期结果')"/><el-button link type="danger" @click="form.data.steps.splice(i,1)"><Icon name="Delete" :size="16"/></el-button></div><el-form-item :label="$t('模拟结果（仅用于验证平台流程，不代表真实测试）')"><el-select v-model="form.data.simulate_result"><el-option :label="$t('通过')" value="passed"/><el-option :label="$t('失败')" value="failed"/><el-option :label="$t('跳过')" value="skipped"/></el-select></el-form-item></template>
 <template v-if="['plan','flow','suite'].includes(kind)"><el-form-item :label="$t('关联用例')"><el-select v-model="form.data.case_ids" multiple filterable :placeholder="$t('选择本项目中的测试用例')"><el-option v-for="c in cases" :key="c.id" :value="c.id" :label="`${c.name}${c.status!=='ready'?'（未就绪）':''}`"/></el-select></el-form-item><div class="flow-list"><div v-for="(id,i) in form.data.case_ids" :key="id"><span class="step-number">{{Number(i)+1}}</span><span>{{cases.find(c=>c.id===id)?.name||'用例已删除'}}</span><el-button link :disabled="Number(i)===0" @click="move(Number(i),-1)">{{ $t('上移') }}</el-button><el-button link :disabled="Number(i)===form.data.case_ids.length-1" @click="move(Number(i),1)">{{ $t('下移') }}</el-button></div></div><p class="helper">{{ $t('按以上顺序执行。所有关联用例均就绪后才可发起任务。') }}</p></template>
 <el-form-item v-if="kind==='document'" :label="$t('文档正文')"><el-input v-model="form.data.content" type="textarea" :rows="9" :placeholder="$t('输入测试需求、规范或说明，保存后可上传附件。')"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">{{ $t('取消') }}</el-button><el-button type="primary" :loading="saving" @click="save">保存{{title}}</el-button></template></el-dialog>
 <el-drawer :model-value="!!detail" :title="detail?.name" size="650px" @close="detail=null"><template v-if="detail"><div class="inline-actions"><Status :value="detail.status"/><span class="priority" :class="detail.priority">{{detail.priority}}</span><span class="muted">{{fmt(detail.updated_at)}}</span></div><p class="detail-description">{{detail.description||'暂无描述'}}</p><div v-if="kind==='document'" class="document-content">{{detail.data.content||'暂无正文，可上传附件补充文档。'}}</div><div v-if="kind==='case'" class="detail-steps"><h3>{{ $t('测试步骤') }}</h3><div v-for="(s,i) in detail.data.steps" :key="i"><span class="step-number">{{Number(i)+1}}</span><div><strong>{{s.action}}</strong><p>预期：{{s.expected}}</p></div></div></div><p v-if="['plan','flow','suite'].includes(kind)" class="helper">关联用例 ID（依执行顺序）：{{detail.data.case_ids.join(' → ')||'暂无'}}</p><Attachments :asset="detail.id"/></template></el-drawer>
</div></template>
